probes.c1:
from shipping import tier
want = {1: "letter", 250: "letter", 500: "letter", 501: "small", 1200: "small", 2000: "small",
        2001: "parcel", 7000: "parcel", 10000: "parcel"}
for w, t in want.items():
    try:
        got = tier(w)
    except Exception as e:
        raise AssertionError((w, repr(e)))
    assert got == t, (w, got, t)

