from shipping import tier
for w in (0, -1, -500, 10001, 50000):
    try:
        got = tier(w)
    except ValueError:
        continue
    raise AssertionError(("no ValueError", w, got))
for w in (1, 10000):
    try:
        tier(w)
    except Exception as e:
        raise AssertionError((w, repr(e)))
